WITH RankedPosts AS (SELECT p.Id, p.Title, p.CreationDate, p.Score, p.ViewCount, p.OwnerUserId, U.Reputation, RANK() OVER (PARTITION BY p.OwnerUserId ORDER BY p.CreationDate DESC NULLS FIRST) AS PostRank FROM Posts AS p JOIN Users AS U ON p.OwnerUserId = U.Id WHERE p.CreationDate >= CURRENT_DATE() - INTERVAL '1' YEAR), UserBadges AS (SELECT b.UserId, COUNT(b.Id) AS BadgeCount, GROUP_CONCAT(b.Name, ', ') AS BadgeNames FROM Badges AS b GROUP BY b.UserId), PostComments AS (SELECT c.PostId, COUNT(c.Id) AS CommentCount FROM Comments AS c GROUP BY c.PostId), UserActivity AS (SELECT U.Id AS UserId, U.DisplayName, COALESCE(RP.PostCount, 0) AS TotalPosts, COALESCE(UB.BadgeCount, 0) AS TotalBadges, COALESCE(PC.CommentCount, 0) AS TotalComments FROM Users AS U LEFT JOIN (SELECT OwnerUserId, COUNT(Id) AS PostCount FROM Posts GROUP BY OwnerUserId) AS RP ON U.Id = RP.OwnerUserId LEFT JOIN UserBadges AS UB ON U.Id = UB.UserId LEFT JOIN PostComments AS PC ON U.Id = PC.PostId), TopUsers AS (SELECT UA.UserId, UA.DisplayName, UA.TotalPosts, UA.TotalBadges, UA.TotalComments, ROW_NUMBER() OVER (ORDER BY UA.TotalPosts DESC NULLS FIRST, UA.TotalBadges DESC NULLS FIRST) AS UserRank FROM UserActivity AS UA) SELECT TU.DisplayName, TU.TotalPosts, TU.TotalBadges, TU.TotalComments, RP.Title, RP.CreationDate, RP.Score, RP.ViewCount, TU.UserRank FROM TopUsers AS TU LEFT JOIN RankedPosts AS RP ON TU.UserId = RP.OwnerUserId WHERE TU.UserRank <= 10 AND (RP.Score IS NULL OR RP.Score > 10) ORDER BY TU.UserRank